(function () {
  'use strict';

  const SAVE_PREFIX = 'sc_save_';
  const OPTIONS_KEY = 'sc_options';
  const TIMESTAMP_PREFIX = '//T:';

  function getFileInfo(raw) {
    if (!raw) return null;
    const info = { value: raw, timestamp: null };
    const idx = raw.lastIndexOf(TIMESTAMP_PREFIX);
    if (idx > 0) {
      info.value = raw.substr(0, idx);
      info.timestamp = raw.substr(idx + TIMESTAMP_PREFIX.length);
    }
    return info;
  }

  function addTimestamp(content) {
    return content + TIMESTAMP_PREFIX + new Date().toISOString();
  }

  function saveFile(fileName, content) {
    try {
      localStorage.setItem(SAVE_PREFIX + fileName, addTimestamp(content));
    } catch (e) {
      emit('saveerror', JSON.stringify({ error: e.toString() }));
    }
  }

  function deleteFile(fileName) {
    localStorage.removeItem(SAVE_PREFIX + fileName);
  }

  function getFromDisk(fileName) {
    const raw = localStorage.getItem(SAVE_PREFIX + fileName);
    return raw ? getFileInfo(raw) : null;
  }

  function getSaveGames(existingList) {
    const saveGames = existingList && existingList.saveGames ? [...existingList.saveGames] : [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(SAVE_PREFIX)) {
        const fileName = k.slice(SAVE_PREFIX.length);
        if (fileName.startsWith('sg_') && fileName.endsWith('.json') && !saveGames.includes(fileName)) {
          saveGames.push(fileName);
        }
      }
    }
    const result = [];
    for (const fileName of saveGames) {
      const fi = getFromDisk(fileName);
      if (fi) {
        try {
          const sg = JSON.parse(fi.value);
          sg.fileName = fileName;
          if (sg.saveGameName == null) sg.saveGameName = sg.companyName;
          if (sg.lastSaved == null) sg.lastSaved = new Date();
          result.push(sg);
        } catch (e) {}
      }
    }
    emit('savegames', JSON.stringify(result));
  }

  function createOptions() {
    const lang = (navigator.language || 'en').toLowerCase().substring(0, 2);
    const langMap = { fr: 'fr', de: 'de', es: 'es' };
    return {
      fullScreen: false,
      masterVolume: 70,
      musicVolume: 15,
      sfxVolume: 100,
      zoomLevel: { title: '50%', value: 1 },
      installedMods: [],
      language: langMap[lang] || 'en',
      hasCompletedWelcome: false,
      completedAchievements: [],
      timeFormat: '24h',
      temperatureFormat: 'c',
      saveGames: [],
      enabledMods: [],
      helpTopicsSeen: [],
      clientId: ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, c =>
        (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16)),
    };
  }

  function getOptions() {
    const raw = localStorage.getItem(OPTIONS_KEY);
    let opts = null;
    if (raw) { try { opts = JSON.parse(raw); } catch (e) {} }
    if (!opts) opts = createOptions();
    if (!opts.enabledMods) opts.enabledMods = [];
    emit('options', JSON.stringify(opts));
    return opts;
  }

  function saveOptions(opts) {
    try {
      localStorage.setItem(OPTIONS_KEY, JSON.stringify(opts));
    } catch (e) {}
  }

  function syncMods() {
    emit('mods', JSON.stringify([]));
  }

  function activateAchievement(name) {
    try {
      const raw = localStorage.getItem(OPTIONS_KEY);
      let opts = raw ? JSON.parse(raw) : createOptions();
      if (!opts.completedAchievements) opts.completedAchievements = [];
      if (!opts.completedAchievements.includes(name)) {
        opts.completedAchievements.push(name);
        localStorage.setItem(OPTIONS_KEY, JSON.stringify(opts));
      }
    } catch (e) {}
  }

  function getDebug() {
    emit('debug', JSON.stringify({
      steamCloudEnabled: false,
      steamEnabled: false,
      steamSubscribed: false,
      steamId: 0,
      saveGameFolderPath: 'localStorage',
      modsFolder: 'n/a',
      scndError: false,
    }));
  }

  function emit(channel, data) {
    window.dispatchEvent(new CustomEvent('__disk__' + channel, { detail: data }));
  }

  window.__diskBridge = {
    send: function (channel, data) { handleMessage(channel, data); },
    addEventListener: function (type, fn) {
      if (type === 'ipc-message') {
        window.addEventListener('__disk__ipc', function (e) {
          fn({ channel: e.detail.channel, args: e.detail.args });
        });
      }
    },
  };

  function handleMessage(channel, data) {
    switch (channel) {
      case 'save-file': {
        try {
          const parsed = typeof data === 'string' ? JSON.parse(data) : data;
          saveFile(parsed.fileName, JSON.stringify(parsed.content));
        } catch (e) {
          emit('saveerror', JSON.stringify({ error: e.toString() }));
        }
        break;
      }
      case 'delete-file':       deleteFile(data); break;
      case 'get-save-games':    getSaveGames(data); break;
      case 'get-options':       getOptions(); break;
      case 'save-options': {
        try { saveOptions(typeof data === 'string' ? JSON.parse(data) : data); } catch (e) {}
        break;
      }
      case 'activate-achievement': activateAchievement(data); break;
      case 'get-debug':            getDebug(); break;
      case 'discord-update':       break;
    }
  }

  function emitStartupSequence() {
    syncMods();
    getDebug();
    const raw = localStorage.getItem(OPTIONS_KEY);
    let loaded = null;
    if (raw) { try { loaded = JSON.parse(raw); } catch (e) {} }
    if (!loaded) loaded = createOptions();
    if (!loaded.enabledMods) loaded.enabledMods = [];
    emit('options', JSON.stringify(loaded));
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(emitStartupSequence, 0); });
  } else {
    setTimeout(emitStartupSequence, 0);
  }

})();
